code.source:
#include <iostream>
using namespace std;

class Walker {
public:
    void walk() const { cout << "walks" << endl; }
};

class Swimmer {
public:
    void swim() const { cout << "swims" << endl; }
};

class Duck : public Walker, public Swimmer {};

int main() {
    Duck d;
    d.walk();
    d.swim();
    return 0;
}

#include <iostream>
using namespace std;

class Animal {
public:
    int legs = 2;
};

class Walker : virtual public Animal {};
class Swimmer : virtual public Animal {};
class Duck : public Walker, public Swimmer {};

int main() {
    Duck d;
    d.legs = 4;
    cout << d.legs << endl;
    return 0;
}

